#!/usr/bin/env python3
from __future__ import annotations

import ast
import re
import textwrap
from pathlib import Path

ROOT = Path(__file__).resolve().parents[2]


def read(path: str) -> str:
    return (ROOT / path).read_text(encoding="utf-8")


def write(path: str, text: str) -> None:
    (ROOT / path).write_text(text, encoding="utf-8")


def replace_once(text: str, old: str, new: str, label: str) -> str:
    count = text.count(old)
    if count != 1:
        raise AssertionError(f"{label}: expected exactly one occurrence, found {count}")
    return text.replace(old, new, 1)


def find_callable_span(source: str, name: str, class_name: str | None = None):
    tree = ast.parse(source)
    matches = []
    if class_name is None:
        for node in ast.walk(tree):
            if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)) and node.name == name:
                matches.append(node)
    else:
        for node in tree.body:
            if isinstance(node, ast.ClassDef) and node.name == class_name:
                for child in node.body:
                    if isinstance(child, (ast.FunctionDef, ast.AsyncFunctionDef)) and child.name == name:
                        matches.append(child)
    if len(matches) != 1:
        raise AssertionError(f"callable {class_name or '*'}::{name}: expected 1, found {len(matches)}")
    node = matches[0]
    return node.lineno - 1, node.end_lineno, node.col_offset


def replace_callable(path: str, name: str, replacement: str, class_name: str | None = None) -> None:
    source = read(path)
    start, end, _ = find_callable_span(source, name, class_name)
    lines = source.splitlines(keepends=True)
    replacement = textwrap.dedent(replacement).rstrip() + "\n"
    lines[start:end] = [replacement]
    write(path, "".join(lines))


def remove_callable(path: str, name: str, class_name: str | None = None) -> None:
    source = read(path)
    start, end, _ = find_callable_span(source, name, class_name)
    lines = source.splitlines(keepends=True)
    lines[start:end] = []
    write(path, "".join(lines))


def insert_before_return(path: str, func_name: str, code: str) -> None:
    source = read(path)
    tree = ast.parse(source)
    fn = next((n for n in tree.body if isinstance(n, ast.FunctionDef) and n.name == func_name), None)
    if fn is None:
        raise AssertionError(f"function {func_name} not found in {path}")
    returns = [n for n in ast.walk(fn) if isinstance(n, ast.Return)]
    if not returns:
        raise AssertionError(f"function {func_name} has no return")
    ret = max(returns, key=lambda n: n.lineno)
    lines = source.splitlines(keepends=True)
    indent = " " * ret.col_offset
    block = textwrap.indent(textwrap.dedent(code).strip() + "\n", indent)
    lines[ret.lineno - 1:ret.lineno - 1] = [block]
    write(path, "".join(lines))


