sim = "aurora_simulation_engine.py"
s = read(sim)
start_marker = "# Stopwords stripped during semantic topic extraction."
end_marker = "class ConsciousLearner:"
start = s.find(start_marker)
end = s.find(end_marker)
if start < 0 or end < 0 or end <= start:
    raise AssertionError("Build 725 semantic-parser removal markers not found")
replacement_block = '''# Build 725: semantic subject identity is NOT derived in the simulation learner.\n# Raw wording remains raw wording. A resolved semantic topic can enter this layer\n# only when Aurora's native meaning/representation machinery explicitly supplies\n# one. The only string-shape test retained here is a one-time migration detector\n# for prose generated by the now-removed learner template; it never chooses or\n# resolves a topic.\n_LEGACY_OUTCOME_META_PHRASES: Tuple[str, ...] = (\n    "built connection when approached with",\n    "opened depth when approached with",\n    "held attention when approached with",\n    "creates friction when approached with",\n    "caused withdrawal when approached with",\n    "still shallow in my web",\n)\n\n\ndef _is_legacy_outcome_meta(text: Any) -> bool:\n    value = str(text or "").strip().lower()\n    if not value:\n        return False\n    return any(phrase in value for phrase in _LEGACY_OUTCOME_META_PHRASES)\n\n\n'''
s = s[:start] + replacement_block + s[end:]
# New typed evidence fields. Default is deliberately non-semantic.
s = replace_once(
    s,
    '    outcome_axis: str = ""\n',
    '    outcome_axis: str = ""\n    evidence_kind: str = "response_outcome"\n    evidence: Dict[str, Any] = field(default_factory=dict)\n',
    "UnderstandingShard typed evidence fields",
)
write(sim, s)

replace_callable(sim, "set_dps", r'''
    def set_dps(self, dps) -> None:
        """Attach DPS for compatibility and purge legacy outcome prose.

        Build 725 removes the learner->DPS semantic write route entirely.  DPS
        remains attached because other systems legitimately own it, but outcome
        telemetry can never be stamped into semantic facets again.
        """
        self._dps = dps
        self._purge_legacy_dps_outcome_facets()

    def _purge_legacy_dps_outcome_facets(self) -> int:
        if self._dps is None:
            return 0
        removed = 0
        try:
            for crystal in getattr(self._dps, "crystals", {}).values():
                facets = getattr(crystal, "facets", None)
                if not isinstance(facets, dict):
                    continue
                for facet_id, facet in list(facets.items()):
                    if str(getattr(facet, "role", "") or "") != "understanding":
                        continue
                    if _is_legacy_outcome_meta(getattr(facet, "content", "")):
                        facets.pop(facet_id, None)
                        removed += 1
        except Exception:
            return removed
        return removed
''', class_name="ConsciousLearner")

replace_callable(sim, "observe_outcome", r'''
    def observe_outcome(self, selected: ConceptualResponse,
                        observation: ConversationObservation,
                        context_type: str,
                        oets_web=None,
                        semantic_topic: str = "",
                        topic_resolution_status: str = "unresolved",
                        episode_source: str = "ordinary") -> Optional[UnderstandingShard]:
        """Record experiential response-outcome evidence, never semantic prose.

        Build 725 removes raw-prompt topic parsing and the generated
        ``"X built connection when approached with Y"`` understanding route.
        This layer may receive an already-resolved native semantic identity, but
        it never manufactures one and response-outcome evidence is permanently
        typed as non-semantic.
        """
        self.total_observations += 1
        meaningful = (
            observation.avatar_engaged
            or observation.conversation_deepened
            or observation.connection_felt_stronger
        )
        if not meaningful and not observation.tension_arose:
            return None

        outcome_label, axis = self._outcome_axis(observation)
        if not axis:
            return None

        semantic_topic = str(semantic_topic or "").strip()
        topic_resolution_status = (
            "resolved"
            if semantic_topic and str(topic_resolution_status or "") == "resolved"
            else "unresolved"
        )
        episode_source = str(episode_source or "ordinary")
        evidence = {
            "outcome": outcome_label,
            "outcome_axis": axis,
            "response_concept": selected.primary_concept.value,
            "semantic_topic": semantic_topic,
            "episode_source": episode_source,
        }

        existing = self._find_similar(
            selected.primary_concept, context_type,
            semantic_topic, axis, episode_source,
        )
        if existing:
            existing.strengthen()
            existing.evidence_kind = "response_outcome"
            existing.evidence.update(evidence)
            existing.understanding = ""
            return existing

        shard = UnderstandingShard(
            shard_id=_generate_id("understand"),
            response_concept=selected.primary_concept,
            observation_summary=observation.describe(),
            understanding="",
            context_type=context_type,
            episode_source=episode_source,
            semantic_topic=semantic_topic,
            topic_resolution_status=topic_resolution_status,
            outcome_axis=axis,
            evidence_kind="response_outcome",
            evidence=evidence,
        )
        self.shards[shard.shard_id] = shard
        self._by_concept[selected.primary_concept].append(shard.shard_id)
        return shard
''', class_name="ConsciousLearner")

replace_callable(sim, "_outcome_axis", r'''
    def _outcome_axis(self, obs: ConversationObservation) -> Tuple[str, str]:
        """Map observed consequence to structural evidence labels + IVM axis."""
        if obs.tension_arose:
            return "friction", "B-axis"
        if obs.avatar_pulled_back:
            return "withdrawal", "X-axis contraction"
        if obs.connection_felt_stronger:
            return "connection_stronger", "A-axis relief"
        if obs.conversation_deepened:
            return "conversation_deepened", "T-axis expansion"
        if obs.avatar_engaged:
            return "attention_held", "N-axis resonance"
        return "", ""
''', class_name="ConsciousLearner")

replace_callable(sim, "check_admission", r'''
    def check_admission(self, shard: UnderstandingShard) -> Tuple[bool, str]:
        """Semantic-memory admission is closed to response-outcome evidence."""
        if str(getattr(shard, "evidence_kind", "") or "") != "semantic_claim":
            return False, "nonsemantic_outcome_evidence"
        if shard.topic_resolution_status != "resolved" or not shard.semantic_topic:
            return False, "unresolved_topic"
        primary = shard.semantic_topic.split("/")[0].strip().lower()
        if not primary or primary in _INTERNAL_MECHANISM_LABELS:
            return False, "internal_mechanism_label_as_subject"
        if not (shard.understanding or "").strip():
            return False, "empty_understanding"
        if _is_legacy_outcome_meta(shard.understanding):
            return False, "legacy_outcome_meta"
        if shard.observation_count < 1 or shard.confidence < 0.55:
            return False, "insufficient_evidence"
        if self._has_unresolved_contradiction(shard):
            return False, "unresolved_contradiction"
        return True, "admissible"
''', class_name="ConsciousLearner")

