replace_callable(sim, "import_state", r'''
    def import_state(self, state: Optional[Dict[str, Any]]) -> int:
        """Restore learner evidence and destructively migrate legacy meta-prose."""
        self.shards = {}
        self._by_concept = defaultdict(list)
        self.total_observations = 0
        if not isinstance(state, dict):
            return 0
        try:
            self.total_observations = int(state.get("total_observations", 0) or 0)
        except Exception:
            self.total_observations = 0

        raw_shards = state.get("shards", []) or []
        if not isinstance(raw_shards, list):
            return 0
        for row in raw_shards:
            if not isinstance(row, dict):
                continue
            concept_name = str(row.get("response_concept", "") or "").strip()
            try:
                concept = ResponseConcept(concept_name)
            except Exception:
                concept = ResponseConcept.THOUGHTFUL_REFLECTION
            shard_id = str(row.get("shard_id", "") or _generate_id("understand"))
            if shard_id in self.shards:
                shard_id = _generate_id("understand")
            try:
                confidence = _clamp(float(row.get("confidence", 0.3) or 0.3), 0.0, 1.0)
            except Exception:
                confidence = 0.3
            try:
                observation_count = max(1, int(row.get("observation_count", 1) or 1))
            except Exception:
                observation_count = 1
            try:
                ts = float(row.get("timestamp", time.time()) or time.time())
            except Exception:
                ts = time.time()

            raw_understanding = str(row.get("understanding", "") or "")
            outcome_axis = str(row.get("outcome_axis", "") or "")
            declared_kind = str(row.get("evidence_kind", "") or "")
            legacy_outcome = bool(outcome_axis) or _is_legacy_outcome_meta(raw_understanding)
            if declared_kind in {"response_outcome", "semantic_claim"}:
                evidence_kind = declared_kind
            elif legacy_outcome:
                evidence_kind = "response_outcome"
            else:
                evidence_kind = "legacy_untyped"

            # The old generated sentence is not preserved in another field:
            # migration removes the contaminant instead of relocating it.
            understanding = "" if evidence_kind == "response_outcome" else raw_understanding
            evidence = dict(row.get("evidence") or {}) if isinstance(row.get("evidence"), dict) else {}
            if evidence_kind == "response_outcome" and legacy_outcome:
                evidence.setdefault("migration", "build725_legacy_outcome_meta_removed")

            if "topic_resolution_status" in row:
                topic_resolution_status = str(row.get("topic_resolution_status", "") or "unresolved")
            else:
                topic_resolution_status = "legacy"
            shard = UnderstandingShard(
                shard_id=shard_id,
                response_concept=concept,
                observation_summary=str(row.get("observation_summary", "") or ""),
                understanding=understanding,
                context_type=str(row.get("context_type", "restored") or "restored"),
                confidence=confidence,
                observation_count=observation_count,
                timestamp=ts,
                episode_source=str(row.get("episode_source", "") or "ordinary"),
                semantic_topic=str(row.get("semantic_topic", "") or ""),
                topic_resolution_status=topic_resolution_status,
                outcome_axis=outcome_axis,
                evidence_kind=evidence_kind,
                evidence=evidence,
            )
            self.shards[shard_id] = shard
            self._by_concept[concept].append(shard_id)
        self._purge_legacy_dps_outcome_facets()
        return len(self.shards)
''', class_name="ConsciousLearner")

