replace_callable(sim, "_topic_from_seed_prompt", r'''
    def _topic_from_seed_prompt(
        self,
        seed_prompt: str,
        base_topic: Optional[Dict[str, Any]] = None,
    ) -> Dict[str, Any]:
        """Normalize transport only; never infer semantic identity from wording."""
        raw_prompt = str(seed_prompt or "").strip()
        topic = dict(base_topic or {})
        if not raw_prompt:
            return topic
        stripped_prompt, episode_source = _strip_internal_transport_marker(raw_prompt)
        stripped_prompt = stripped_prompt.strip() or raw_prompt

        # Native semantic identity may already have been supplied by a caller.
        # Preserve it only when explicitly marked resolved; otherwise the
        # simulation learner receives an unresolved subject rather than a
        # lexical guess.
        supplied_topic = str(topic.get("semantic_topic", "") or "").strip()
        supplied_status = str(topic.get("topic_resolution_status", "") or "")
        if supplied_status != "resolved" or not supplied_topic:
            supplied_topic = ""
            supplied_status = "unresolved"

        low = stripped_prompt.lower()
        category = str(topic.get("category", "") or "")
        if not category:
            # Response-style category is not semantic subject identity.  This
            # legacy response-pool hint remains bounded to strategy selection.
            if "?" in stripped_prompt:
                category = "practical"
            elif any(word in low for word in ("meaning", "coherence", "grounding", "continuity")):
                category = "philosophy"
            elif any(word in low for word in ("feel", "sad", "hurt", "love", "afraid")):
                category = "emotional"
            else:
                category = "practical"

        topic["category"] = category
        topic["prompt"] = stripped_prompt
        topic["topic"] = stripped_prompt
        topic["episode_source"] = episode_source or "ordinary"
        topic["semantic_topic"] = supplied_topic
        topic["topic_resolution_status"] = supplied_status
        topic["expected_tone"] = str(topic.get("expected_tone") or "neutral")
        return topic
''')

