# ---------------------------------------------------------------------------
# 3b. OETS persisted contamination cleanup, including old learned_behavior nodes.
# ---------------------------------------------------------------------------
oets_path = "aurora_internal/aurora_ontological_scaffolding.py"
o = read(oets_path)
needle = "    def get_node(self, word: str) -> Optional[SemanticNode]:\n"
if needle not in o:
    raise AssertionError("OntologicalWeb.get_node anchor not found")
method = r'''
    def purge_legacy_learner_outcome_nodes(self) -> int:
        """Remove nodes minted by the deleted response-outcome prose bridge."""
        phrases = (
            "built connection when approached with",
            "opened depth when approached with",
            "held attention when approached with",
            "creates friction when approached with",
            "caused withdrawal when approached with",
            "still shallow in my web",
        )
        doomed = []
        for word, node in list(self.nodes.items()):
            lineage = str(getattr(node, "lineage", "") or "")
            role = str(getattr(node, "role", "") or "")
            if not (lineage.startswith("learner:") or role == "learned_behavior"):
                continue
            texts = []
            for definition in list(getattr(node, "definitions", []) or []):
                if isinstance(definition, dict):
                    texts.append(str(definition.get("text") or definition.get("definition") or ""))
                else:
                    texts.append(str(getattr(definition, "text", "") or getattr(definition, "definition", "") or definition))
            blob = " ".join(texts).lower()
            if any(phrase in blob for phrase in phrases) or "when_approached_with" in str(word).lower():
                doomed.append(word)

        for word in doomed:
            node = self.nodes.get(word)
            rel_ids = [
                rid for rid, rel in list(self.relations.items())
                if getattr(rel, "source_word", None) == word or getattr(rel, "target_word", None) == word
            ]
            for rid in rel_ids:
                rel = self.relations.pop(rid, None)
                if rel is None:
                    continue
                self._relations_by_source.get(rel.source_word, set()).discard(rid)
                self._relations_by_target.get(rel.target_word, set()).discard(rid)
                self._relations_by_type.get(rel.relation_type, set()).discard(rid)
            if node is not None:
                self._nodes_by_role.get(str(getattr(node, "role", "") or ""), set()).discard(word)
                for cluster_id in list(getattr(node, "cluster_ids", set()) or set()):
                    self._nodes_by_cluster.get(cluster_id, set()).discard(word)
            category = self._word_to_category.pop(word, None)
            if category:
                self._semantic_categories.get(category, set()).discard(word)
            self.nodes.pop(word, None)
        return len(doomed)

'''
o = o.replace(needle, method + needle, 1)
# Make all ordinary reads sanitize first. This is not a filter over returned
# prose; it destructively removes the obsolete persisted nodes from live state.
